function ForgingDialog:OnInitialize()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        GameUtils.Request(
                Interfaces.MakeCallHome,
                {},
                function(request, response)
                    if checkInt(response.errCode) == 0 then
                        ForgingComponent:StopTimer()
                        --printInfo("=========>>"..table.dump(response.data))
                        ForgingComponent:InitialDojo(response.data)--这边初始的数据供其他子节点使用
                        ForgingComponent:SetArgVo()
                        self:SetMaxGrade()
                        --ForgingComponent:TryOpenUpgradePopup()
                        self:CalculateMaxProducedNum()
                        self:CalculateCycleBlockData(ForgingComponent.timeLeft)
                        self:FreshLeftUI()
                        self:FreshRightUI()

                    end
                end
        )
    end))
    return coWait
end

---通关最新关卡id获取对应的制造等级数据
---@param questId number
function ForgingDialog:GetForgingGradeDataByQuestId(questId)
    local passedQuestData
    local forgingGradeData
    if checkNumber(questId) == 0 then --没有挑战通关过
        forgingGradeData = CfUtils.GetCfVo(AutoIds.IdSetting1821, "ForgingGradeVo", 1)
    else
        passedQuestData = QuestConfMgr:GetInstance():GetQuestVoById(questId)
        forgingGradeData = CfUtils.GetCfVo(AutoIds.IdSetting1821, "ForgingGradeVo", passedQuestData.regionLevel)
    end
    return forgingGradeData
end

---计算右侧面板当前选择的生产的周期最大数量
function ForgingDialog:CalculateMaxProducedNum()
    local goodsHasNum = GoodsUtils.GetThingNo(ForgingComponent.goodsIdExpend)
    ---当前材料的可生产数X = 持有材料总数 / 单次消耗数量，向下取整
    local x = math.floor(goodsHasNum / ForgingComponent.cycleExpendNum)
    local forgingGradeData = self:GetForgingGradeDataByQuestId(ForgingComponent.questId)
    --printInfo("forgingGradeData--->>>"..table.dump(forgingGradeData))
    ---剩余未生产的周期数remainingCycleNum
    local remainingCycleNum = math.ceil(ForgingComponent.timeLeft / ForgingComponent.cycleTimes)
    ---当前上限下的剩余可生产周期Y = （上限 – 已生产数）/ 单次绪晶生产数 – 剩余未生产的周期数  [[只需计算普通道具奖励的上限]]
    local y = (checkNumber(forgingGradeData.maxNormal) - (ForgingComponent.makeCallNum + (ForgingComponent.currentOverMakeTimes * ForgingComponent.cycleProducedNum))) / ForgingComponent.cycleProducedNum - remainingCycleNum
    ---当前时间下的剩余可生产周期Z = 到下周一0点的剩余时间/ 单次生产时间 – 剩余未生产的周期数
    local z = math.floor(ForgingComponent.closeTimeLeft / ForgingComponent.cycleTimes) - remainingCycleNum
    local w = ForgingComponent.cycleLimit - remainingCycleNum - ForgingComponent.currentOverMakeTimes
    self.maxChooseProducedNum = math.max(0, math.min(x, y, z, w))
    self.maxChooseProducedNum = math.tointeger(self.maxChooseProducedNum)
end

---计算右侧面板当前选择的生产的周期最大数量(除去材料的限制)
function ForgingDialog:GetMaxProducedNum2()
    --local goodsHasNum = GoodsUtils.GetThingNo(ForgingComponent.goodsIdExpend)
    ---当前材料的可生产数X = 持有材料总数 / 单次消耗数量，向下取整
    --local x = math.floor(goodsHasNum / ForgingComponent.cycleExpendNum)
    local forgingGradeData = self:GetForgingGradeDataByQuestId(ForgingComponent.questId)
    --printInfo("forgingGradeData--->>>"..table.dump(forgingGradeData))
    ---剩余未生产的周期数remainingCycleNum
    local remainingCycleNum = math.ceil(ForgingComponent.timeLeft / ForgingComponent.cycleTimes)
    ---当前上限下的剩余可生产周期Y = （上限 – 已生产数）/ 单次绪晶生产数 – 剩余未生产的周期数  [[只需计算普通道具奖励的上限]]
    local y = (checkNumber(forgingGradeData.maxNormal) - (ForgingComponent.makeCallNum + (ForgingComponent.currentOverMakeTimes * ForgingComponent.cycleProducedNum))) / ForgingComponent.cycleProducedNum - remainingCycleNum
    ---当前时间下的剩余可生产周期Z = 到下周一0点的剩余时间/ 单次生产时间 – 剩余未生产的周期数
    local z = math.floor(ForgingComponent.closeTimeLeft / ForgingComponent.cycleTimes) - remainingCycleNum
    local w = ForgingComponent.cycleLimit - remainingCycleNum - ForgingComponent.currentOverMakeTimes
    local maxChooseProducedNum = math.max(0, math.min(y, z, w))
    maxChooseProducedNum = math.tointeger(maxChooseProducedNum)
    return maxChooseProducedNum
end

function ForgingDialog:CalculateCycleBlockData(countDown)
    self.blockNumFinish = ForgingComponent.currentOverMakeTimes---ForgingComponent.currentMakeNum / ForgingComponent.cycleProducedNum
    local integer = math.floor(countDown / ForgingComponent.cycleTimes)
    local remainder = math.fmod(countDown, ForgingComponent.cycleTimes)
    --printInfo("remainder---11---->>"..remainder)
    if remainder == 0 and integer >= 1 then
        remainder = ForgingComponent.cycleTimes
        integer = integer - 1
    end
    --printInfo("remainder----22--->>"..remainder)
    self.blockNumDoing = remainder > 0 and 1 or 0
    self.blockNumWait = integer
    --printInfo("blockNumDoing-------->>"..self.blockNumDoing)
    --printInfo("blockNumWait-------->>"..self.blockNumWait)
    --printInfo("blockNumFinish-------->>"..self.blockNumFinish)
    if remainder > 0 then
        self:StartLeftSecond(remainder)
    end
end

