function ForgingDialog:FreshProgressBlock()
    local blockCount = self.blockNumFinish + self.blockNumDoing + self.blockNumWait--需要的gameObject数量
    local blockGoCount = table.count(self.blockGoList)--已有的gameObject数量
    if blockGoCount > blockCount then--复用时隐藏多出来的
        for i = blockCount + 1, blockGoCount do
            KTool.SetActive(self.blockGoList[i], false)
        end
    end
    for i = 1, blockCount do
        local go
        go = self.blockGoList[i]
        if not go then
            go = CfUtils.InstantiateGo(self.ImgCycle, self.LayoutCycleGroup.gameObject)
            go.name = "block"..i
            self.blockGoList[i] = go.gameObject
        end
        local onGoing = go.transform:Find("ImgOngoing")
        if i <= self.blockNumWait then
            KTool.SetActive(onGoing, false)
            CfUtils.SetUISwitchImage(go, 3)
        elseif i <= (self.blockNumWait + self.blockNumDoing) then
            KTool.SetActive(onGoing, true)
            CfUtils.SetUISwitchImage(go, 2)
        elseif i <= blockCount then
            KTool.SetActive(onGoing, false)
            CfUtils.SetUISwitchImage(go, 1)
        end
        KTool.SetActive(go, true)
    end
end

function ForgingDialog:SetMaxGrade()
    local forgingGradeVo = CfUtils.GetWholeVo(AutoIds.IdSetting1821, "ForgingGradeVo")
    self.maxForgingGrade = checkNumber(forgingGradeVo[#forgingGradeVo].id)
end

function ForgingDialog:FreshRightUI()
    self.TxtNumberCycleExpend.text = ForgingComponent.cycleExpendNum
    local path = GoodsConfMgr:GetInstance():GetPhotoPathById(ForgingComponent.goodsIdExpend)
    self.ImgIconExpend:LoadSprite(path)
    self:FreshProducedDesc()
    SetButtonAction(self.BtnReduce, function ()
        if self.curChooseProducedNum == 0 then return end
        self.curChooseProducedNum = self.curChooseProducedNum - 1
        self:FreshProducedDesc()
    end)
    SetButtonAction(self.BtnImgMin, function ()
        if self.curChooseProducedNum == 0 then return end
        self.curChooseProducedNum = 0
        self:FreshProducedDesc()
    end)
    SetButtonAction(self.BtnAdd, function ()
        if self.maxChooseProducedNum == 0 then
            local goodsHasNum = GoodsUtils.GetThingNo(ForgingComponent.goodsIdExpend)
            ---当前材料的可生产数X = 持有材料总数 / 单次消耗数量，向下取整
            local x = math.floor(goodsHasNum / ForgingComponent.cycleExpendNum)
            if x == 0 then
                GoodsUtils.CheckConsumeDataCondition({
                    {
                        goodsId = ForgingComponent.goodsIdExpend,
                        goodsNum = ForgingComponent.cycleExpendNum,
                    }
                })
                --GameUtils.Toast(localize("材料不足"))
                return
            end
            GameUtils.Toast(localize("本周已无法继续制造"))
            return
        end
        if self.maxChooseProducedNum == self.curChooseProducedNum then
            local num = self:GetMaxProducedNum2()
            if self.curChooseProducedNum >= num  then
                GameUtils.Toast(localize("已达到最大值"))
                return
            end

            local goodsHasNum = GoodsUtils.GetThingNo(ForgingComponent.goodsIdExpend)
            ---当前材料的可生产数X = 持有材料总数 / 单次消耗数量，向下取整
            local x = math.floor(goodsHasNum / ForgingComponent.cycleExpendNum)
            if x - checkNumber(self.curChooseProducedNum) <= 0 then
                GoodsUtils.CheckConsumeDataCondition({
                    {
                        goodsId = ForgingComponent.goodsIdExpend,
                        goodsNum = ForgingComponent.cycleExpendNum * (self.curChooseProducedNum + 1),
                    }
                })
                --GameUtils.Toast(localize("材料不足"))
                return
            end
        end
        if self.curChooseProducedNum < self.maxChooseProducedNum then
            self.curChooseProducedNum = self.curChooseProducedNum + 1
            self:FreshProducedDesc()
        end
    end)
    SetButtonAction(self.BtnImgMax, function ()
        self.curChooseProducedNum = self.maxChooseProducedNum
        if self.maxChooseProducedNum == 0 then
            local goodsHasNum = GoodsUtils.GetThingNo(ForgingComponent.goodsIdExpend)
            ---当前材料的可生产数X = 持有材料总数 / 单次消耗数量，向下取整
            local x = math.floor(goodsHasNum / ForgingComponent.cycleExpendNum)
            if x == 0 then
                GoodsUtils.CheckConsumeDataCondition({
                    {
                        goodsId = ForgingComponent.goodsIdExpend,
                        goodsNum = ForgingComponent.cycleExpendNum,
                    }
                })
                --GameUtils.Toast(localize("材料不足"))
                return
            end
            GameUtils.Toast(localize("本周已无法继续制造"))
            return
        end
        self:FreshProducedDesc()
    end)
    SetButtonAction(self.FontStyleButtonProduced, function ()
        self:BtnActionProduce()
    end)
    self.TextNumberCycle.onEndEdit:AddListener(function()
        self.TextNumberCycle.text = Mathf.Clamp(checkNumber(self.TextNumberCycle.text), 0, self.maxChooseProducedNum)
    end)
end

---刷新右上的生产消耗、耗时、产出等描述
function ForgingDialog:FreshProducedDesc()
    self.TextNumberCycle.text = self.curChooseProducedNum
    self.TextNumberExpend.text = self.curChooseProducedNum * ForgingComponent.cycleExpendNum
    self.TextTimeExpand.text = CfUtils.GetTimeHMS2(self.curChooseProducedNum * ForgingComponent.cycleTimes)
    self.TextNumberTransition1.text = self.curChooseProducedNum * ForgingComponent.cycleProducedNum
    self.TextNumberTransition2.text = self.curChooseProducedNum * ForgingComponent.cycleExtraProducedNum
    local isGrey = self.maxChooseProducedNum == 0 or self.curChooseProducedNum == 0
    self.FontStyleButtonProduced:GetComponent("FontStyleButton"):ResetFontStyle(isGrey and "B5" or "B1")
end

---领奖励按钮事件
function ForgingDialog:BtnActionDrawRewards()
    if ForgingComponent.currentOverMakeTimes > 0 then
        GameUtils.Request(
                Interfaces.MakeCallDrawCallReward,
                {  },
                function(request, response)
                    if checkInt(response.errCode) == 0 then
                        local co = cs_coroutine.start(function()
                            UIRaycastBlocker:AddCondition("ForgingDialogGetRewards")
                            KTool.SetActive(self.ReceiveAnim, false)
                            self.MachineAnimRoot:Play("Open")
                            if isNull(self.openAnimTime) then
                                self.openAnimTime = CfUtils.GetAnimatorTime(self.MachineAnimRoot.transform, "ForgingDialogMachineOpen")
                            end
                            cs_coroutine.yield_return(Yielders.GetWaitForSeconds(self.openAnimTime))
                            GoodsUtils.DrawRewards(response.data.rewards)
                            UIRaycastBlocker:RemoveCondition("ForgingDialogGetRewards")
                            UIModule.OpenDialog(
                                    {
                                        id = Constants.UITypeIds.UICommonRewardPop,
                                        parameters = { rewards = response.data.rewards , cb = function ()
                                            self.isBeforeGetReward = true
                                            ForgingComponent.makeCallNum = ForgingComponent.makeCallNum + (ForgingComponent.currentOverMakeTimes * ForgingComponent.cycleProducedNum)--ForgingComponent.currentMakeNum
                                            ForgingComponent.activityCallNum = ForgingComponent.activityCallNum + (ForgingComponent.currentOverMakeTimes * ForgingComponent.cycleExtraProducedNum)
                                            ForgingComponent.currentOverMakeTimes = 0
                                            self:CalculateCycleBlockData(ForgingComponent.timeLeft)
                                            self:FreshLeftUI()
                                            self:CalculateMaxProducedNum()
                                        end}
                                    }
                            )
                        end)
                        table.insert(self.coroutineList, co)
                    end
                end
        )
    else
        GameUtils.Toast(localize("当前没有可领取奖励"))
    end
end

---生产按钮事件
function ForgingDialog:BtnActionProduce()
    if self.maxChooseProducedNum == 0 then
        local goodsHasNum = GoodsUtils.GetThingNo(ForgingComponent.goodsIdExpend)
        ---当前材料的可生产数X = 持有材料总数 / 单次消耗数量，向下取整
        local x = math.floor(goodsHasNum / ForgingComponent.cycleExpendNum)
        if x == 0 then
            GoodsUtils.CheckConsumeDataCondition({
                {
                    goodsId = ForgingComponent.goodsIdExpend,
                    goodsNum = ForgingComponent.cycleExpendNum,
                }
            })
            --GameUtils.Toast(localize("材料不足"))
            return
        end
        GameUtils.Toast(localize("本周已无法继续制造"))
        return
    end
    if self.curChooseProducedNum == 0 then
        GameUtils.Toast(localize("未设置生产周期"))
        return
    end
    if self.curChooseProducedNum > 0 and self.curChooseProducedNum <= self.maxChooseProducedNum then
        GameUtils.Request(
                Interfaces.MakeCallMakeCall,
                { makeCallTimes = self.curChooseProducedNum },
                function(request, response)
                    if checkInt(response.errCode) == 0 then
                        GoodsUtils.ConsumeGoods({{
                             goodsId = ForgingComponent.goodsIdExpend,
                             num = self.curChooseProducedNum * ForgingComponent.cycleExpendNum
                         }}, true)
                        ForgingComponent.timeLeft = ForgingComponent.timeLeft + self.curChooseProducedNum * ForgingComponent.cycleTimes
                        self:CalculateCycleBlockData(ForgingComponent.timeLeft)
                        self:FreshLeftUI()
                        self:CalculateMaxProducedNum()
                        self.curChooseProducedNum = 0
                        self:FreshProducedDesc()
                    end
                end
        )
    end
end

---一个生产周期结束
function ForgingDialog:OneCycleFinish()
    --数据更新
    ForgingComponent.currentOverMakeTimes = ForgingComponent.currentOverMakeTimes + 1
    --ForgingComponent.currentMakeNum = ForgingComponent.currentMakeNum + ForgingComponent.cycleProducedNum
    self:CalculateCycleBlockData(ForgingComponent.timeLeft)
    self:FreshLeftUI()
end

function ForgingDialog:StartLeftSecond(countDown)
    self:StopTimer()
    --printInfo("countDown---->>"..countDown)
    countDown = checkNumber(countDown)
    self.TextTime.text = CfUtils.GetTimeHMS2(countDown)
    self.timer = CDTimerModule:AddCD(1, function (count, id)
        --printInfo("count--->>"..ForgingComponent.timeLeft)
        self.TextTime.text = CfUtils.GetTimeHMS2(count)
        ForgingComponent.timeLeft = ForgingComponent.timeLeft - 1
        if count == 0 then
            self:OneCycleFinish()
        end
    end, countDown, false, true, true)
    --CS.UnityEngine.UI.LayoutRebuilder.ForceRebuildLayoutImmediate(self.TextCountdownNode)
end

function ForgingDialog:StopTimer()
    if not isNull(self.timer) then
        CDTimerModule:RemoveCD(self.timer)
        self.timer = nil
    end
end

function ForgingDialog:StopCoroutine()
    if not isNull(self.coroutineList) then
        for k, v in pairs(self.coroutineList) do
            cs_coroutine.stop(v)
        end
    end
end

function ForgingDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        self:StopTimer()
        self:StopCoroutine()
        ForgingComponent:CalculateCycleBlockData(ForgingComponent.timeLeft)
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

return ForgingDialog